#include <cuda_fp16.h>

constexpr int VEC = 4;
typedef float4 vec_t;

__global__ void fused_ops_kernel(
    const vec_t* __restrict__ conv_out,
    const float* __restrict__ bias,
    vec_t* __restrict__ output,
    int N, int C, int H, int W,
    float scaling_factor) {

    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total_vecs = (N * C * H * W + VEC-1) / VEC;
    if (idx >= total_vecs) return;

    vec_t in = conv_out[idx];
    vec_t out;

    const int linear_base = idx * VEC;
    const int c = (linear_base / (H * W)) % C;
    const float bias_val = __ldg(&bias[c]);
    const float upper_bound = scaling_factor > 1.0f ? (1.0f / scaling_factor) : 1.0f;

    #pragma unroll
    for(int i = 0; i < VEC; ++i) {
        float val = (&in.x)[i] + bias_val;
        val = fmaxf(val, 0.0f);
        val = fminf(val, 1.0f);
        val = fminf(val, upper_bound);
        (&out.x)[i] = val;
    }

    output[idx] = out;
}

