l1_norm_source = """
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <ATen/cuda/CUDAContext.h>

__global__ void l1_norm_kernel(const float* __restrict__ input,
                               float* __restrict__ output,
                               int num_rows) {
    extern __shared__ float smem[];
    const int row = blockIdx.x;
    const int tid = threadIdx.x;
    const int lane_id = tid % 32;
    const int warp_id = tid / 32;

    constexpr int elements_per_thread = 16;
    const float4* row_ptr = reinterpret_cast<const float4*>(input + row * 16384);
    float4* out_row = reinterpret_cast<float4*>(output + row * 16384);

    float sum = 0.0f;

    #pragma unroll
    for(int i = 0; i < elements_per_thread; ++i) {
        float4 vec = __ldg(&row_ptr[tid + i * 256]);
        sum += fabsf(vec.x) + fabsf(vec.y) + fabsf(vec.z) + fabsf(vec.w);
    }

    // Warp reduction
    sum += __shfl_down_sync(0xffffffff, sum, 16);
    sum += __shfl_down_sync(0xffffffff, sum, 8);
    sum += __shfl_down_sync(0xffffffff, sum, 4);
    sum += __shfl_down_sync(0xffffffff, sum, 2);
    sum += __shfl_down_sync(0xffffffff, sum, 1);

    if(lane_id == 0)
        smem[warp_id] = sum;
    __syncthreads();

    // Block reduction
    if(warp_id == 0) {
        float val = lane_id < 8 ? smem[lane_id] : 0.0f;
        val += __shfl_down_sync(0xffffffff, val, 4);
        val += __shfl_down_sync(0xffffffff, val, 2);
        val += __shfl_down_sync(0xffffffff, val, 1);

        if(lane_id == 0)
            smem[0] = val;
    }
    __syncthreads();

    const float inv_sum = __fdividef(1.0f, smem[0] + 1e-8f);

    #pragma unroll
    for(int i = 0; i < elements_per_thread; ++i) {
        float4 vec = __ldg(&row_ptr[tid + i * 256]);
        vec.x *= inv_sum;
        vec.y *= inv_sum;
        vec.z *= inv_sum;
        vec.w *= inv_sum;
        out_row[tid + i * 256] = vec;
    }
}

torch::Tensor l1_norm_cuda(torch::Tensor x) {
    auto output = torch::empty_like(x);
    int num_rows = x.size(0);

    dim3 grid(num_rows);
    constexpr int block_size = 256;
    size_t smem = (block_size / 32) * sizeof(float);

    l1_norm_kernel<<<grid, block_size, smem, at::cuda::getCurrentCUDAStream()>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        num_rows
    );

    return output;
}
"""

