template<typename scalar_t>
__device__ void lstm_cell(
    const scalar_t* input,
    const scalar_t* hidden,
    const scalar_t* cell,
    const scalar_t* weight_ih,
    const scalar_t* weight_hh,
    const scalar_t* bias_ih,
    const scalar_t* bias_hh,
    scalar_t* next_hidden,
    scalar_t* next_cell,
    int input_size,
    int hidden_size) {

    const int idx = threadIdx.x;
    if (idx >= hidden_size) return;

    scalar_t ig = bias_ih[idx] + bias_hh[idx];
    scalar_t fg = bias_ih[idx + hidden_size] + bias_hh[idx + hidden_size];
    scalar_t gg = bias_ih[idx + 2*hidden_size] + bias_hh[idx + 2*hidden_size];
    scalar_t og = bias_ih[idx + 3*hidden_size] + bias_hh[idx + 3*hidden_size];

    for (int k = 0; k < input_size; ++k) {
        const scalar_t w_i = weight_ih[(0 * hidden_size + idx) * input_size + k];
        const scalar_t w_f = weight_ih[(1 * hidden_size + idx) * input_size + k];
        const scalar_t w_g = weight_ih[(2 * hidden_size + idx) * input_size + k];
        const scalar_t w_o = weight_ih[(3 * hidden_size + idx) * input_size + k];

        ig += input[k] * w_i;
        fg += input[k] * w_f;
        gg += input[k] * w_g;
        og += input[k] * w_o;
    }

    for (int k = 0; k < hidden_size; ++k) {
        const scalar_t w_i = weight_hh[(0 * hidden_size + idx) * hidden_size + k];
        const scalar_t w_f = weight_hh[(1 * hidden_size + idx) * hidden_size + k];
        const scalar_t w_g = weight_hh[(2 * hidden_size + idx) * hidden_size + k];
        const scalar_t w_o = weight_hh[(3 * hidden_size + idx) * hidden_size + k];

        ig += hidden[k] * w_i;
        fg += hidden[k] * w_f;
        gg += hidden[k] * w_g;
        og += hidden[k] * w_o;
    }

    const scalar_t i = 1.0f / (1.0f + exp(-ig));
    const scalar_t f = 1.0f / (1.0f + exp(-fg));
    const scalar_t g = tanh(gg);
    const scalar_t o = 1.0f / (1.0f + exp(-og));

    const scalar_t c = f * cell[idx] + i * g;
    next_cell[idx] = c;
    next_hidden[idx] = o * tanh(c);
}

