#include <cuda_runtime.h>
#include <cooperative_groups.h>
#include <cooperative_groups/reduce.h>

namespace cg = cooperative_groups;

__global__ void subtract_mean_logsumexp_kernel(
    const float* input, const float* sub, float* output,
    int out_features, int batch_size) {

    const int row = blockIdx.x;
    const int tid = threadIdx.x;
    constexpr int vec_size = 4;
    const int n_vectors = out_features / vec_size;

    const float4* input_vec = reinterpret_cast<const float4*>(input);
    const float4* sub_vec = reinterpret_cast<const float4*>(sub);

    // Vectorized subtraction and sum
    float4 in_val = input_vec[row * n_vectors + tid];
    float4 s_val = sub_vec[tid];

    float sum = (in_val.x - s_val.x) + 
                (in_val.y - s_val.y) + 
                (in_val.z - s_val.z) + 
                (in_val.w - s_val.w);

    // Warp reduction
    auto warp = cg::tiled_partition<32>(cg::this_thread_block());
    float warp_sum = cg::reduce(warp, sum, cg::plus<float>());

    // Block reduction
    __shared__ float shared[32];
    if (warp.thread_rank() == 0) {
        shared[warp.meta_group_rank()] = warp_sum;
    }
    __syncthreads();

