#include <torch/extension.h>
#include <cuda_fp16.h>

#define TILE_SIZE 32
#define UNROLL 8
#define VECTOR_LOAD 4
#define WARP_SIZE 32

__global__ void triu_matmul_kernel(const float* __restrict__ A,
                                  const float* __restrict__ B,
                                  float* __restrict__ C,
                                  int N) {
    const int block_x = blockIdx.x;
    const int block_y = blockIdx.y;
    if (block_x > block_y) return;

    const int row_start = block_x * TILE_SIZE;
    const int col_start = block_y * TILE_SIZE;

    __shared__ float As[2][TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[2][TILE_SIZE][TILE_SIZE];

    float sum[TILE_SIZE/WARP_SIZE][TILE_SIZE/WARP_SIZE] = {{0}};

    const int tx = threadIdx.x % WARP_SIZE;
    const int ty = threadIdx.x / WARP_SIZE;

    const int num_tiles = (N + TILE_SIZE - 1) / TILE_SIZE;

    for (int t = 0; t < num_tiles; ++t) {
        // Vectorized loads for A
        int a_row = row_start + ty * VECTOR_LOAD;
        int a_col = t * TILE_SIZE + tx * VECTOR_LOAD;
        if (a_row < N && a_col < N) {
            float4 a_val = *reinterpret_cast<const float4*>(&A[a_row * N + a_col]);
            #pragma unroll
            for (int i = 0; i < VECTOR_LOAD; ++i) {
                if (a_col + i >= a_row)
                    As[t%2][ty * VECTOR_LOAD + i][tx] = a_val.x;
                a_val = make_float4(a_val.y, a_val.z, a_val.w, 0.0f);
            }
        }

        // Transposed vectorized loads for B
        int b_row = t * TILE_SIZE + ty * VECTOR_LOAD;
        int b_col = col_start + tx * VECTOR_LOAD;
        if (b_row < N && b_col < N && b_col >= b_row) {
            float4 b_val = *reinterpret_cast<const float4*>(&B[b_row * N + b_col]);
            #pragma unroll
            for (int i = 0; i < VECTOR_LOAD; ++i) {
                Bs[t%2][tx][ty * VECTOR_LOAD + i] = b_val.x;
                b_val = make_float4(b_val.y, b_val.z, b_val.w, 0.0f);
            }
        }

        __syncthreads();

        // Double buffered computation
        if(t > 0) {
            #pragma unroll
            for (int k = 0; k < TILE_SIZE; k += UNROLL) {
                #pragma unroll
                for (int i = 0; i < UNROLL; ++i) {
                    sum[ty][tx] += As[(t-1)%2][threadIdx.y][k + i] * 
                                  Bs[(t-1)%2][k + i][threadIdx.x];
                }
            }
        }
        __syncthreads();
    }

    // Store results with upper triangular check
    const int row = row_start + threadIdx.y;
    const int col = col_start + threadIdx.x;
    if (row < N && col < N && col >= row) {
        C[row * N + col] = sum[ty][tx];
    }
}

torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros_like(A);

    dim3 block(TILE_SIZE, TILE_SIZE);
    int grid_dim = (N + TILE_SIZE - 1) / TILE_SIZE;
    dim3 grid(grid_dim, grid_dim);

    triu_matmul_kernel<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
