#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void gru_forward_kernel(const float* input, const float* h0, const float* weight_ih, const float* weight_hh, 
                                   const float* bias_ih, const float* bias_hh, float* output, int seq_len, int batch_size, 
                                   int input_size, int hidden_size, int num_layers) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < seq_len * batch_size * hidden_size) {
        int seq_idx = idx / (batch_size * hidden_size);
        int batch_idx = (idx % (batch_size * hidden_size)) / hidden_size;
        int hidden_idx = idx % hidden_size;

        float h_prev = h0[batch_idx * hidden_size + hidden_idx];
        float input_val = input[seq_idx * batch_size * input_size + batch_idx * input_size + hidden_idx];
        float weight_ih_val = weight_ih[hidden_idx * input_size + hidden_idx];
        float weight_hh_val = weight_hh[hidden_idx * hidden_size + hidden_idx];
        float bias_ih_val = bias_ih[hidden_idx];
        float bias_hh_val = bias_hh[hidden_idx];

        float r = 1.0f / (1.0f + expf(-(input_val * weight_ih_val + h_prev * weight_hh_val + bias_ih_val + bias_hh_val)));
