#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_conv_bn_scale_kernel(
    const float* input, const float* weight, const float* bias, 
    const float* running_mean, const float* running_var, 
    float* output, int batch_size, int in_channels, int out_channels, 
    int height, int width, int kernel_size, float scaling_factor, float eps) {

    int h_out = height - kernel_size + 1;
    int w_out = width - kernel_size + 1;
    int out_size = batch_size * out_channels * h_out * w_out;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < out_size) {
        int b = idx / (out_channels * h_out * w_out);
        int oc = (idx / (h_out * w_out)) % out_channels;
        int oh = (idx / w_out) % h_out;
        int ow = idx % w_out;

        float sum = 0.0f;
        for (int ic = 0; ic < in_channels; ++ic) {
            for (int kh = 0; kh < kernel_size; ++kh) {
                for (int kw = 0; kw < kernel_size; ++kw) {
                    int ih = oh + kh;
                    int iw = ow + kw;
                    sum += input[b * in_channels * height * width + ic * height * width + ih * width + iw] *
