        sum += bias[oc];

        // Batch Normalization
        float mean = running_mean[oc];
        float var = running_var[oc];
        float normalized = (sum - mean) / sqrtf(var + eps);

        // Scaling
        output[idx] = normalized * scaling_factor;
    }
}

