from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for argmin
argmin_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void argmin_kernel(const float* x, long* out, int batch_size, int dim1, int dim2, int dim) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * dim2) {
        int batch_idx = idx / dim2;
        int dim2_idx = idx % dim2;
        float min_val = x[batch_idx * dim1 * dim2 + dim2_idx];
        long min_idx = 0;
        for (int i = 1; i < dim1; i++) {
            float val = x[batch_idx * dim1 * dim2 + i * dim2 + dim2_idx];
            if (val < min_val) {
                min_val = val;
                min_idx = i;
            }
        }
        out[batch_idx * dim2 + dim2_idx] = min_idx;
    }
}

__global__ void argmin_kernel_shared(const float* x, long* out, int batch_size, int dim1, int dim2, int dim) {
    extern __shared__ float shared[];
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * dim2) {
        int batch_idx = idx / dim2;
        int dim2_idx = idx % dim2;
        float min_val = x[batch_idx * dim1 * dim2 + dim2_idx];
        long min_idx = 0;
        for (int i = 1; i < dim1; i++) {
            float val = x[batch_idx * dim1 * dim2 + i * dim2 + dim2_idx];
            if (val < min_val) {
                min_val = val;
                min_idx = i;
            }
        }
        shared[threadIdx.x] = min_idx;
        __syncthreads();
        if (threadIdx.x == 0) {
            out[batch_idx * dim2 + dim2_idx] = shared[0];
        }
    }
}

__global__ void argmin_kernel_warp(const float* x, long* out, int batch_size, int dim1, int dim2, int dim) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * dim2) {
        int batch_idx = idx / dim2;
        int dim2_idx = idx % dim2;
        float min_val = x[batch_idx * dim1 * dim2 + dim2_idx];
        long min_idx = 0;
        for (int i = 1; i < dim1; i++) {
            float val = x[batch_idx * dim1 * dim2 + i * dim2 + dim2_idx];
            if (val < min_val) {
                min_val = val;
                min_idx = i;
            }
        }
        int warp_idx = threadIdx.x & 31;
        int warp_id = threadIdx.x >> 5;
        __shared__ long warp_min_idx[32];
        warp_min_idx[warp_idx] = min_idx;
        __syncthreads();
        for (int i = 16; i > 0; i >>= 1) {
            if (warp_idx < i) {
                if (warp_min_idx[warp_idx + i] < warp_min_idx[warp_idx]) {
                    warp_min_idx[warp_idx] = warp_min_idx[warp_idx + i];
                }
            }
            __syncthreads();
        }
        if (warp_idx == 0) {
            out[batch_idx * dim2 + dim2_idx] = warp_min_idx[0];
        }
    }
}

torch::Tensor argmin_cuda(torch::Tensor x, int dim) {
    auto batch_size = x.size(0);
    auto dim1 = x.size(1);
    auto dim2 = x.size(2);
    auto out = torch::zeros({batch_size, dim2}, torch::TensorOptions().dtype(torch::kLong).device(x.device()));

