linear_relu_source = """
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cublas_v2.h>

#define BLOCK_SIZE 128
#define WARPS_PER_BLOCK 4
#define WARP_SIZE 32

__global__ void linear_relu_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int B, int in_dim, int out_dim) {

    __shared__ float smem[BLOCK_SIZE][BLOCK_SIZE+1];

    const int warp_id = threadIdx.x / WARP_SIZE;
    const int lane_id = threadIdx.x % WARP_SIZE;
    const int row = blockIdx.x * WARPS_PER_BLOCK + warp_id;

    if(row >= B) return;

    float sum[2] = {0};
    if(lane_id < 2) sum[lane_id] = bias[blockIdx.y*2 + lane_id];

    const int num_tiles = (in_dim + BLOCK_SIZE - 1) / BLOCK_SIZE;

    for(int t=0; t<num_tiles; t++) {
        const int in_offset = t * BLOCK_SIZE;

        if(in_offset + threadIdx.x < in_dim) {
            smem[threadIdx.x][warp_id] = input[row * in_dim + in_offset + threadIdx.x];
        } else {
            smem[threadIdx.x][warp_id] = 0.0f;
        }
        __syncthreads();

        #pragma unroll
        for(int i=0; i<BLOCK_SIZE; i+=WARP_SIZE) {
            const float val = smem[i + lane_id][warp_id];
            #pragma unroll
            for(int j=0; j<2; j++) {
                const float w = weight[(blockIdx.y*2 + j)*in_dim + in_offset + i + lane_id];
                sum[j] += val * w;
            }
        }
        __syncthreads();
    }

    if(threadIdx.x < 2 && row < B && blockIdx.y*2 + threadIdx.x < out_dim) {
        output[row * out_dim + blockIdx.y*2 + threadIdx.x] = fmaxf(sum[threadIdx.x], 0.0f);
    }
}

torch::Tensor linear_relu_forward(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {

    const int B = input.size(0);
    const int in_dim = input.size(1);
    const int out_dim = weight.size(0);

    auto output = torch::zeros({B, out_dim}, input.options());

    dim3 blocks(B, (out_dim + 1)/2);
    dim3 threads(BLOCK_SIZE);

    linear_relu_kernel<<<blocks, threads, sizeof(float)*BLOCK_SIZE*(BLOCK_SIZE+1)>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        B, in_dim, out_dim
    );

    return output;
}
