class Conv2dReLU(nn.Module):
    def __init__(self, in_c, out_c, kernel_size=3, stride=1, padding=1):
        super().__init__()
        self.stride = stride
        self.padding = padding
        self.weight = nn.Parameter(torch.Tensor(out_c, in_c, kernel_size, kernel_size))
        self.bias = nn.Parameter(torch.Tensor(out_c))
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        return custom_ops.conv2d_relu_forward(
            x, self.weight, self.bias,
            3, self.stride, self.padding
        )

class LinearReLU(nn.Module):
    def __init__(self, in_dim, out_dim):
        super().__init__()
        self.weight = nn.Parameter(torch.Tensor(out_dim, in_dim))
        self.bias = nn.Parameter(torch.Tensor(out_dim))
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        return custom_ops.linear_relu_forward(x, self.weight, self.bias)

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()

        self.features = nn.Sequential(
            Conv2dReLU(3, 64),
            Conv2dReLU(64, 64),
            nn.MaxPool2d(2, 2),

            Conv2dReLU(64, 128),
            Conv2dReLU(128, 128),
            nn.MaxPool2d(2, 2),

            Conv2dReLU(128, 256),
            Conv2dReLU(256, 256),
            Conv2dReLU(256, 256),
            nn.MaxPool2d(2, 2),

            Conv2dReLU(256, 512),
            Conv2dReLU(512, 512),
            Conv2dReLU(512, 512),
            nn.MaxPool2d(2, 2),

            Conv2dReLU(512, 512),
            Conv2dReLU(512, 512),
            Conv2dReLU(512, 512),
            nn.MaxPool2d(2, 2)
        )

        self.classifier = nn.Sequential(
            LinearReLU(512*7*7, 4096),
            LinearReLU(4096, 4096),
            nn.Linear(4096, num_classes)
        )

    def forward(self, x):
        x = self.features(x)
        x = torch.flatten(x, 1)
        x = self.classifier(x)
        return x
