#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

#define TILE_SIZE 32
#define UNROLL_FACTOR 4

__device__ __forceinline__ float fast_gelu(float x) {
    const float a = 0.7978845608f;  // sqrt(2/pi)
    const float b = 0.044715f;
    float cube = x * x * x;
    float tanh_arg = a * (x + b * cube);
    return 0.5f * x * (1.0f + tanhf(tanh_arg));
}

__global__ void fused_linear_div_gelu_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float inv_divisor,
    int batch_size,
    int input_size,
    int output_size
) {
    const int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    const int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    __shared__ float input_tile[TILE_SIZE][TILE_SIZE+1];
    __shared__ float weight_tile[TILE_SIZE][TILE_SIZE+1];

    float sum = 0.0f;

    for (int t = 0; t < (input_size + TILE_SIZE - 1) / TILE_SIZE; ++t) {
        int input_col = t * TILE_SIZE + threadIdx.x;
        int weight_row = t * TILE_SIZE + threadIdx.y;

        if (input_col < input_size && row < batch_size) {
            input_tile[threadIdx.y][threadIdx.x] = input[row * input_size + input_col];
        } else {
            input_tile[threadIdx.y][threadIdx.x] = 0.0f;
        }

        if (weight_row < input_size && col < output_size) {
            weight_tile[threadIdx.y][threadIdx.x] = weight[weight_row * output_size + col];
        } else {
            weight_tile[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        #pragma unroll 4
        for (int k = 0; k < TILE_SIZE; ++k) {
            sum += input_tile[threadIdx.y][k] * weight_tile[k][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < batch_size && col < output_size) {
        sum = (sum + bias[col]) * inv_divisor;
        output[row * output_size + col] = fast_gelu(sum);
    }
}

torch::Tensor fused_linear_div_gelu_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float divisor
) {
    auto batch_size = input.size(0);
