import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# GroupNorm-Tanh-HardSwish-Residual Fusion Kernel
gn_fusion_kernel = '''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 256

__global__ void gn_fusion_kernel(
    const float* input,
    const float* residual,
    float* output,
    const float* gamma,
    const float* beta,
    float eps,
    int N, int C, int H, int W,
    int groups
) {
    int n = blockIdx.x;
    int g = blockIdx.y;
    int channels_per_group = C / groups;
    int c_start = g * channels_per_group;
    int c_end = c_start + channels_per_group;

    extern __shared__ float smem[];
    float* sum = smem;
    float* sum_sq = smem + blockDim.x;

    float thread_sum = 0.0f;
    float thread_sum_sq = 0.0f;

    // First pass: compute sum and sum of squares
    for(int c = c_start + threadIdx.x; c < c_end; c += blockDim.x) {
        for(int hw = 0; hw < H*W; ++hw) {
            float val = input[n*C*H*W + c*H*W + hw];
            thread_sum += val;
            thread_sum_sq += val * val;
        }
    }

    sum[threadIdx.x] = thread_sum;
    sum_sq[threadIdx.x] = thread_sum_sq;
    __syncthreads();

    // Block reduction
    for(int stride = blockDim.x/2; stride > 0; stride >>= 1) {
        if(threadIdx.x < stride) {
            sum[threadIdx.x] += sum[threadIdx.x + stride];
            sum_sq[threadIdx.x] += sum_sq[threadIdx.x + stride];
        }
        __syncthreads();
    }

    float mean = sum[0] / (channels_per_group * H * W);
    float var = (sum_sq[0] / (channels_per_group * H * W)) - (mean * mean);
    float inv_std = rsqrtf(var + eps);

    // Second pass: normalize and apply activations
    for(int c = c_start + threadIdx.x; c < c_end; c += blockDim.x) {
        float gamma_val = gamma[c];
        float beta_val = beta[c];
        for(int hw = 0; hw < H*W; ++hw) {
            int idx = n*C*H*W + c*H*W + hw;
            float x = input[idx];
            float normalized = (x - mean) * inv_std;
            normalized = gamma_val * normalized + beta_val;

            // Tanh + HardSwish
            float tanh_val = tanhf(normalized);
            float hs_val = tanh_val * __fmaf_rz(tanh_val, 0.166666667f, 0.5f);
            hs_val = fminf(fmaxf(hs_val, 0.0f), 1.0f) * tanh_val;

            output[idx] = residual[idx] + hs_val;
        }
    }
}

torch::Tensor gn_fusion_cuda(
    torch::Tensor input,
    torch::Tensor residual,
    torch::Tensor gamma,
    torch::Tensor beta,
    float eps,
    int groups
) {
    auto N = input.size(0);
    auto C = input.size(1);
    auto H = input.size(2);
    auto W = input.size(3);

    auto output = torch::empty_like(input);

    dim3 grid(N, groups);
    int block = min(BLOCK_SIZE, (int)(C/groups));
    size_t smem = 2 * block * sizeof(float);

    gn_fusion_kernel<<<grid, block, smem>>>(
        input.data_ptr<float>(),
        residual.data_ptr<float>(),
        output.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        eps,
        N, (int)C, H, W,
        groups
    );

    return output;
}
'''

# LogSumExp Kernel with Warp Reduction
lse_kernel = '''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__inline__ __device__ float warp_reduce_max(float val) {
    for(int offset = 16; offset > 0; offset >>= 1)
        val = fmaxf(val, __shfl_down_sync(0xffffffff, val, offset));
    return val;
}

__inline__ __device__ float warp_reduce_sum(float val) {
    for(int offset = 16; offset > 0; offset >>= 1)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__global__ void logsumexp_kernel(const float* input, float* output, int C, int HW) {
    int n = blockIdx.x;
    int hw = blockIdx.y * blockDim.x + threadIdx.x;

    if(hw >= HW) return;

    float max_val = -INFINITY;
    for(int c = 0; c < C; ++c) {
        float val = input[n*C*HW + c*HW + hw];
        max_val = fmaxf(max_val, val);
    }

    max_val = warp_reduce_max(max_val);

    float sum_exp = 0.0f;
    for(int c = 0; c < C; ++c) {
        float val = input[n*C*HW + c*HW + hw];
        sum_exp += expf(val - max_val);
    }

    sum_exp = warp_reduce_sum(sum_exp);
    if(threadIdx.x % 32 == 0) {
        output[n*HW + hw] = logf(sum_exp) + max_val;
    }
}

torch::Tensor logsumexp_cuda(torch::Tensor input) {
    auto N = input.size(0);
    auto C = input.size(1);
    auto H = input.size(2);
    auto W = input.size(3);
    int HW = H * W;

    auto output = torch::empty({N, 1, H, W}, input.options());

    dim3 grid(N, (HW + 255)/256);
    logsumexp_kernel<<<grid, 256>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        (int)C,
        HW
    );

    return output;
}
