#define CHECK_CUDA(x) TORCH_CHECK(x.device().is_cuda(), #x " must be CUDA tensor")

__global__ void window_partition_shift_kernel(
    const float* input, float* output,
    int B, int padded_H, int padded_W, int C,
    int window_size, int shift_size,
    int n_windows
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = B * n_windows * window_size * window_size * C;
    if (idx >= total_elements) return;

    int window_area = window_size * window_size;
    int elements_per_window = window_area * C;

    int b = idx / (n_windows * elements_per_window);
    int rem = idx % (n_windows * elements_per_window);
    int win = rem / elements_per_window;
    rem = rem % elements_per_window;
    int c = rem % C;
    int pos = rem / C;
    int x = pos % window_size;
    int y = pos / window_size;

    int windows_per_row = padded_W / window_size;
    int window_y = win / windows_per_row;
    int window_x = win % windows_per_row;

    int src_x = window_x * window_size + x - shift_size;
    int src_y = window_y * window_size + y - shift_size;

    int input_idx = b * padded_H * padded_W * C + 
                   src_y * padded_W * C + 
                   src_x * C + c;

    if (src_x >= 0 && src_x < padded_W && src_y >= 0 && src_y < padded_H) {
        output[idx] = input[input_idx];
    } else {
        output[idx] = 0.0f;
    }
}

__global__ void spatial_mlp_kernel(
    const float* input, const float* weights,
    float* output,
    int num_windows, int window_area,
    int num_heads, int head_dim
) {    
    int window_idx = blockIdx.x;
    int head_idx = blockIdx.y;
    int thread_id = threadIdx.x;

    const float* W = weights + head_idx * window_area * window_area;
    float* out = output + (window_idx * num_heads + head_idx) * window_area * head_dim;
    const float* inp = input + (window_idx * num_heads + head_idx) * window_area * head_dim;

    for (int i = thread_id; i < window_area * head_dim; i += blockDim.x) {
        int row = i / head_dim;
        int col = i % head_dim;
        float sum = 0.0f;

        for (int k = 0; k < window_area; k++) {
            sum += W[row * window_area + k] * inp[k * head_dim + col];
        }

        out[i] = sum;
    }
}

__global__ void fused_mlp_kernel(
    const float* input, 
    const float* fc1_weight, const float* fc1_bias,
    const float* fc2_weight, const float* fc2_bias,
    float* output,
    int in_features, int hidden_features, int out_features,
    float drop_prob, bool training,
    unsigned long long seed, unsigned long long offset
) {
    int batch_idx = blockIdx.x;
    int out_idx = blockIdx.y;
    int tid = threadIdx.x;

    extern __shared__ float shared[];
    float* partial_sums = shared;

    partial_sums[tid] = fc2_bias[out_idx];

    for (int h = tid; h < hidden_features; h += blockDim.x) {
        float sum = fc1_bias[h];
        for (int i = 0; i < in_features; i++) {
            sum += input[batch_idx * in_features + i] * fc1_weight[i * hidden_features + h];
        }
        float gelu = 0.5f * sum * (1.0f + erff(sum / sqrtf(2.0f)));

        if (training) {
            curandStatePhilox4_32_10_t state;
            curand_init(seed, h, offset, &state);
            float rand = curand_uniform(&state);
            if (rand > drop_prob) {
                partial_sums[tid] += gelu / (1.0f - drop_prob) * fc2_weight[h * out_features + out_idx];
            }
        } else {
            partial_sums[tid] += gelu * fc2_weight[h * out_features + out_idx];
        }
    }

    __syncthreads();

    for (int s = blockDim.x/2; s > 0; s >>= 1) {
        if (tid < s) {
            partial_sums[tid] += partial_sums[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        output[batch_idx * out_features + out_idx] = partial_sums[0];
    }
