__global__ void lstm_layer_kernel(
    const float* input,
    const float* weights_ih,
    const float* weights_hh,
    const float* bias_ih,
    const float* bias_hh,
    float* output,
    float* hidden_state,
    float* cell_state,
    int batch_size,
    int seq_len,
    int input_size,
    int hidden_size
) {
    int batch_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int hid_idx = blockIdx.y * blockDim.y + threadIdx.y;

    if (batch_idx >= batch_size || hid_idx >= hidden_size) return;

    float h_prev = hidden_state[batch_idx * hidden_size + hid_idx];
    float c_prev = cell_state[batch_idx * hidden_size + hid_idx];

    for (int t = 0; t < seq_len; ++t) {
        const float* x_t = input + batch_idx * seq_len * input_size + t * input_size;

