        for (int i = 0; i < input_size; ++i) {
            float x_val = x_t[i];
            int idx_ih_i = (0 * hidden_size + hid_idx) * input_size + i;
            int idx_ih_f = (1 * hidden_size + hid_idx) * input_size + i;
            int idx_ih_g = (2 * hidden_size + hid_idx) * input_size + i;
            int idx_ih_o = (3 * hidden_size + hid_idx) * input_size + i;

            igate += weights_ih[idx_ih_i] * x_val;
            fgate += weights_ih[idx_ih_f] * x_val;
            ggate += weights_ih[idx_ih_g] * x_val;
            ogate += weights_ih[idx_ih_o] * x_val;
        }

        // Hidden to hidden (corrected weight indexing)
        for (int i = 0; i < hidden_size; ++i) {
            float h_val = hidden_state[batch_idx * hidden_size + i];
            int idx_hh_i = (0 * hidden_size + hid_idx) * hidden_size + i;
            int idx_hh_f = (1 * hidden_size + hid_idx) * hidden_size + i;
            int idx_hh_g = (2 * hidden_size + hid_idx) * hidden_size + i;
