#include <torch/extension.h>
#include <cuda.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

#define VEC 4
#define TILE_SIZE 128
#define BLOCK_SIZE 256

__global__ void conv_transpose_1d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_length,
    int out_length,
    int kernel_size,
    int stride,
    int padding,
    int dilation) {

    const int ol = blockIdx.x * TILE_SIZE + threadIdx.x;
    const int oc = blockIdx.y;
    const int b = blockIdx.z;

    if (b >= batch_size || oc >= out_channels) return;

    __shared__ float smem_input[TILE_SIZE][VEC];
    __shared__ float smem_weight[TILE_SIZE][VEC];

    float sum = 0.0f;
    const int vec_channels = in_channels / VEC;

    for (int k = 0; k < kernel_size; ++k) {
        const int base_pos = ol + padding - k * dilation;
        const int il = base_pos / stride;
        const int remainder = base_pos % stride;

        if (remainder != 0 || il < 0 || il >= in_length) continue;

        for (int vec_idx = 0; vec_idx < vec_channels; ++vec_idx) {
            const int ic = vec_idx * VEC;

            // Cooperative loading of input and weight vectors
            if (threadIdx.x < VEC) {
                smem_input[threadIdx.x][threadIdx.x] = input[(b * in_channels + ic + threadIdx.x) * in_length + il];
                smem_weight[threadIdx.x][threadIdx.x] = weight[(ic + threadIdx.x) * out_channels * kernel_size + oc * kernel_size + k];
            }
            __syncthreads();

            #pragma unroll
            for (int v = 0; v < VEC; ++v) {
                sum += smem_input[v][v] * smem_weight[v][v];
            }
            __syncthreads();
        }

        // Handle remaining channels not divisible by VEC
        for (int ic = vec_channels * VEC; ic < in_channels; ++ic) {
            sum += input[(b * in_channels + ic) * in_length + il] 
                 * weight[ic * out_channels * kernel_size + oc * kernel_size + k];
        }
    }

    if (ol < out_length) {
        if (bias) sum += __ldg(&bias[oc]);
        output[(b * out_channels + oc) * out_length + ol] = sum;
    }
}

