__global__ void gru_forward_kernel(
    const float* input, const float* hidden,
    const float* w_ih, const float* w_hh,
    const float* b_ih, const float* b_hh,
    float* new_hidden, int input_size, int hidden_size,
    int batch_size)
{
    int bid = blockIdx.x;
    int tid = threadIdx.x;

    if (bid >= batch_size || tid >= hidden_size) return;

    const float* x = input + bid * input_size;
    const float* h = hidden + bid * hidden_size;
    float* h_new = new_hidden + bid * hidden_size;

    // Input gate calculations
    float ir = b_ih[tid];
    float iz = b_ih[tid + hidden_size];
    float in_ = b_ih[tid + 2*hidden_size];

    // Hidden gate calculations
    float hr = b_hh[tid];
    float hz = b_hh[tid + hidden_size];
    float hn = b_hh[tid + 2*hidden_size];

    // Matrix multiplications
    for(int j=0; j<input_size; ++j) {
        float x_j = x[j];
        ir += x_j * w_ih[j + tid * input_size];
        iz += x_j * w_ih[j + (tid + hidden_size) * input_size];
        in_ += x_j * w_ih[j + (tid + 2*hidden_size) * input_size];
    }

    for(int j=0; j<hidden_size; ++j) {
        float h_j = h[j];
        hr += h_j * w_hh[j + tid * hidden_size];
        hz += h_j * w_hh[j + (tid + hidden_size) * hidden_size];
        hn += h_j * w_hh[j + (tid + 2*hidden_size) * hidden_size];
