# Optimized fused BatchNorm-Tanh with vectorized channel reduction
fused_batchnorm_tanh_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

constexpr int VEC_SIZE = 4;
constexpr int REDUCTION_THREADS = 512;

__global__ void channel_reduce_kernel(
    const float* __restrict__ input,
    float* __restrict__ sum_out,
    float* __restrict__ sqsum_out,
    int C, int N, int H, int W
) {
    extern __shared__ float sdata[];
    float* s_sum = sdata;
    float* s_sqsum = sdata + blockDim.x;

    int c = blockIdx.x;
    int elements_per_channel = N * H * W;
    int tid = threadIdx.x;

    float sum = 0.0f, sqsum = 0.0f;

    // Vectorized load with float4
    const int vec_stride = blockDim.x * VEC_SIZE;
    for (int i = tid * VEC_SIZE; i < elements_per_channel; i += vec_stride) {
        float4 vals = *reinterpret_cast<const float4*>(input + c * elements_per_channel + i);
        sum += vals.x + vals.y + vals.z + vals.w;
        sqsum += vals.x*vals.x + vals.y*vals.y + vals.z*vals.z + vals.w*vals.w;
    }

    s_sum[tid] = sum;
    s_sqsum[tid] = sqsum;
    __syncthreads();

    // Parallel reduction
    for (int s = blockDim.x/2; s >= 32; s >>= 1) {
        if (tid < s) {
            s_sum[tid] += s_sum[tid + s];
            s_sqsum[tid] += s_sqsum[tid + s];
        }
        __syncthreads();
    }

    // Warp-level reduction
    if (tid < 32) {
        for (int s = 16; s > 0; s >>= 1) {
            s_sum[tid] += __shfl_down_sync(0xffffffff, s_sum[tid], s);
            s_sqsum[tid] += __shfl_down_sync(0xffffffff, s_sqsum[tid], s);
        }
    }

    if (tid == 0) {
        sum_out[c] = s_sum[0];
        sqsum_out[c] = s_sqsum[0];
    }
}

__global__ void fused_batchnorm_tanh_kernel(
    const float* __restrict__ input,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    float eps,
    float* __restrict__ output,
    int numel,
    int C, int N, int H, int W
) {
    const int tid = blockIdx.x * blockDim.x * VEC_SIZE + threadIdx.x * VEC_SIZE;
    if (tid >= numel) return;

    float4 in = *reinterpret_cast<const float4*>(input + tid);
    float4 out;

    #pragma unroll
    for (int i = 0; i < VEC_SIZE; ++i) {
        int pos = tid + i;
        if (pos >= numel) continue;

        int c = (pos / (H * W)) % C;
        float inv_std = rsqrtf(var[c] + eps);
        float bn_val = (in.x - mean[c]) * inv_std * gamma[c] + beta[c];
        out.x = tanhf(bn_val);

        // Rotate through vector components
        float tmp = in.x; in.x = in.y; in.y = in.z; in.z = in.w; in.w = tmp;
        tmp = out.x; out.x = out.y; out.y = out.z; out.z = out.w; out.w = tmp;
    }

    *reinterpret_cast<float4*>(output + tid) = out;
}

torch::Tensor fused_batchnorm_tanh_cuda(
    torch::Tensor input,
    torch::Tensor gamma,
    torch::Tensor beta,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    float eps,
    float momentum,
    bool training
) {
    auto output = torch::empty_like(input);
    int numel = input.numel();
    int C = input.size(1);
    int N = input.size(0);
    int H = input.size(2);
    int W = input.size(3);

    torch::Tensor mean, var;

    if (training) {
        auto sum = torch::zeros(C, input.options());
        auto sqsum = torch::zeros(C, input.options());

        int smem_size = 2 * REDUCTION_THREADS * sizeof(float);
        channel_reduce_kernel<<<C, REDUCTION_THREADS, smem_size>>>(
            input.data_ptr<float>(),
            sum.data_ptr<float>(),
            sqsum.data_ptr<float>(),
            C, N, H, W
        );

        auto elements_per_channel = N * H * W;
        mean = sum / elements_per_channel;
        var = (sqsum / elements_per_channel) - mean * mean;

        running_mean.copy_((1 - momentum) * running_mean + momentum * mean);
        running_var.copy_((1 - momentum) * running_var + momentum * var);
    } else {
        mean = running_mean;
        var = running_var;
    }

    const int block_size = 512;
    const int grid_size = (numel + block_size * VEC_SIZE - 1) / (block_size * VEC_SIZE);

    fused_batchnorm_tanh_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        eps,
        output.data_ptr<float>(),
        numel,
        C, N, H, W
    );

    return output;
}

// Corrected 2x2 max pool kernel with proper indexing
__global__ void max_pool2x2_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int H, int W
) {
    const int H_out = H / 2;
    const int W_out = W / 2;

    // Calculate output indices
    int total_nc = blockIdx.z;
    int n = total_nc / C;
    int c = total_nc % C;

    int h_out = blockIdx.y * blockDim.y + threadIdx.y;
    int w_out = blockIdx.x * blockDim.x + threadIdx.x;

    if (n >= N || c >= C || h_out >= H_out || w_out >= W_out) return;

    int h_start = h_out * 2;
    int w_start = w_out * 2;

    float max_val = -INFINITY;
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            int h_in = h_start + i;
            int w_in = w_start + j;
            if (h_in < H && w_in < W) {
                int input_idx = n * C * H * W + c * H * W + h_in * W + w_in;
                max_val = fmaxf(max_val, input[input_idx]);
            }
        }
    }

    int output_idx = n * C * H_out * W_out + c * H_out * W_out + h_out * W_out + w_out;
    output[output_idx] = max_val;
}

torch::Tensor max_pool2x2_cuda(torch::Tensor input) {
    auto N = input.size(0);
    auto C = input.size(1);
    auto H = input.size(2);
    auto W = input.size(3);
    auto H_out = H / 2;
    auto W_out = W / 2;
    auto output = torch::empty({N, C, H_out, W_out}, input.options());

    dim3 block(16, 16);
    dim3 grid(
        (W_out + block.x - 1) / block.x,
        (H_out + block.y - 1) / block.y,
        N * C
    );

    max_pool2x2_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H, W
    );

    return output;
}

# Optimized GroupNorm with warp shuffle and vectorization
group_norm_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

constexpr int GROUP_NORM_VEC_SIZE = 4;

__global__ void group_norm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ output,
    int num_groups,
    int channels_per_group,
    int N, int C, int H, int W,
    float eps
) {
    const int group_idx = blockIdx.x;
    const int n = group_idx / num_groups;
    const int g = group_idx % num_groups;
    const int tid = threadIdx.x;
    const int elements_per_group = channels_per_group * H * W;

    __shared__ float s_block_sum;
    __shared__ float s_block_sqsum;

    float sum = 0.0f, sq_sum = 0.0f;

    // Vectorized load
    for (int i = tid * GROUP_NORM_VEC_SIZE; i < elements_per_group; i += blockDim.x * GROUP_NORM_VEC_SIZE) {
        float4 vals = *reinterpret_cast<const float4*>(input + n*C*H*W + g*channels_per_group*H*W + i);
        sum += vals.x + vals.y + vals.z + vals.w;
        sq_sum += vals.x*vals.x + vals.y*vals.y + vals.z*vals.z + vals.w*vals.w;
    }

    // Warp reduction
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
        sq_sum += __shfl_down_sync(0xffffffff, sq_sum, offset);
    }

    // Initialize shared memory
    if (tid == 0) {
        s_block_sum = 0.0f;
        s_block_sqsum = 0.0f;
    }
    __syncthreads();

    if (tid % 32 == 0) {
        atomicAdd(&s_block_sum, sum);
        atomicAdd(&s_block_sqsum, sq_sum);
    }
    __syncthreads();

    const float mean = s_block_sum / elements_per_group;
    const float var = s_block_sqsum / elements_per_group - mean * mean;
    const float inv_std = rsqrtf(var + eps);

    // Vectorized store
    for (int i = tid * GROUP_NORM_VEC_SIZE; i < elements_per_group; i += blockDim.x * GROUP_NORM_VEC_SIZE) {
        float4 vals = *reinterpret_cast<const float4*>(input + n*C*H*W + g*channels_per_group*H*W + i);
        float4 out;
        int c_in_group = (i / (H * W)) % channels_per_group;
        int gamma_beta_idx = g * channels_per_group + c_in_group;
        out.x = (vals.x - mean) * inv_std * gamma[gamma_beta_idx] + beta[gamma_beta_idx];
        out.y = (vals.y - mean) * inv_std * gamma[gamma_beta_idx] + beta[gamma_beta_idx];
        out.z = (vals.z - mean) * inv_std * gamma[gamma_beta_idx] + beta[gamma_beta_idx];
        out.w = (vals.w - mean) * inv_std * gamma[gamma_beta_idx] + beta[gamma_beta_idx];
        *reinterpret_cast<float4*>(output + n*C*H*W + g*channels_per_group*H*W + i) = out;
    }
}

torch::Tensor group_norm_cuda(
    torch::Tensor input,
    torch::Tensor gamma,
    torch::Tensor beta,
    int num_groups,
    float eps
) {
    auto output = torch::empty_like(input);
    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int channels_per_group = C / num_groups;

    dim3 block(256);
    dim3 grid(N * num_groups);

    group_norm_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        num_groups,
        channels_per_group,
        N, C, H, W,
        eps
    );

    return output;
}
"""

