#include <torch/extension.h>
#include <cooperative_groups.h>
#include <cuda_fp16.h>

namespace cg = cooperative_groups;

__global__ void fused_gemv_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight_sum,
    float* __restrict__ output,
    int input_size,
    float scale
) {
    cg::thread_block block = cg::this_thread_block();
    cg::thread_block_tile<32> warp = cg::tiled_partition<32>(block);

    const int batch_idx = blockIdx.x;
    const int tid = threadIdx.x;

    float sum = 0.0f;

    // Vectorized memory access
    const int vec_size = 4;
    int num_vectors = (input_size + vec_size - 1) / vec_size;

    for (int i = tid * vec_size; i < num_vectors * vec_size; i += blockDim.x * vec_size) {
        if(i >= input_size) break;
        float4 vals = *reinterpret_cast<const float4*>(&input[batch_idx * input_size + i]);
        float4 weights = *reinterpret_cast<const float4*>(&weight_sum[i]);

        sum += vals.x * weights.x;
        if (i+1 < input_size) sum += vals.y * weights.y;
        if (i+2 < input_size) sum += vals.z * weights.z;
        if (i+3 < input_size) sum += vals.w * weights.w;
    }

    // Warp-level reduction
    for (int offset = warp.size()/2; offset > 0; offset /= 2)
        sum += warp.shfl_down(sum, offset);

    // Block-level reduction
    if (warp.thread_rank() == 0)
        atomicAdd(&output[batch_idx], sum * scale);
}

torch::Tensor fused_gemv_cuda(
    torch::Tensor input,
    torch::Tensor weight_sum,
    float scaling_factor
) {
    int batch_size = input.size(0);
