    const int gid = blockIdx.x * blockDim.x + threadIdx.x;
    if(gid >= B*H*C) return;

    const int b = gid / (H*C);
    const int h = (gid % (H*C)) / C;
    const int c = gid % C;

    extern __shared__ float smem[];
    float* cumsum = smem + threadIdx.x * L_dim;

    const float* A_ptr = A + ((b*H + h)*C + c)*L_dim;
    for(int i=0; i<L_dim; i++) cumsum[i] = A_ptr[i];

    for(int i=1; i<L_dim; i++) cumsum[i] += cumsum[i-1];

    for(int idx=threadIdx.x; idx<L_dim*L_dim; idx+=blockDim.x) {
        int i = idx / L_dim;
        int j = idx % L_dim;
        L[((((b*H + h)*C + c)*L_dim + i)*L_dim + j)] = 
            (i >= j) ? expf(cumsum[i] - cumsum[j]) : 0.0f;
