    float row_max = smem_max[0];

    float sum_exp = 0.0f;
    for (int i = 0; i < (cols + elements_per_block - 1) / elements_per_block; ++i) {
        int idx = i * elements_per_block + tid * vec_size;
        if (idx < cols) {
