#define TILE_WIDTH 32

__global__ void conv2d_relu_kernel(const float* input, const float* weight, const float* bias, float* output,
                                   int in_channels, int out_channels, int kernel_size, int stride, int padding,
                                   int input_height, int input_width, int output_height, int output_width) {
    int oc = blockIdx.x * TILE_WIDTH + threadIdx.x;
    int oh = blockIdx.y * TILE_WIDTH + threadIdx.y;
    int ow = blockIdx.z * TILE_WIDTH + threadIdx.z;

    __shared__ float shared_input[TILE_WIDTH][TILE_WIDTH];
    __shared__ float shared_weight[TILE_WIDTH][TILE_WIDTH];

    float sum = 0.0f;

    for (int ic = 0; ic < in_channels; ic += TILE_WIDTH) {
        if (threadIdx.y < TILE_WIDTH && threadIdx.z < TILE_WIDTH) {
            int ih = oh * stride + threadIdx.y - padding;
            int iw = ow * stride + threadIdx.z - padding;
            if (ih >= 0 && ih < input_height && iw >= 0 && iw < input_width) {
                shared_input[threadIdx.y][threadIdx.z] = input[(ic + threadIdx.y) * input_height * input_width + ih * input_width + iw];
            } else {
                shared_input[threadIdx.y][threadIdx.z] = 0.0f;
            }
