fused_ops_source = """
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

#define VEC 4
#define BLOCK_SIZE 256

__global__ void fused_bias_scale_sigmoid_kernel(const float* __restrict__ input,
                                                const float* __restrict__ bias,
                                                const float* __restrict__ scale,
                                                float* __restrict__ output,
                                                int num_elements, 
                                                int elements_per_channel,
                                                int num_channels) {
    __shared__ float s_bias;
    __shared__ float s_scale;

    const int blocks_per_channel = gridDim.x / num_channels;
    const int channel_idx = blockIdx.x / blocks_per_channel;
    const int vec_id = (blockIdx.x % blocks_per_channel) * BLOCK_SIZE + threadIdx.x;
    const int idx = vec_id * VEC;

    if (threadIdx.x == 0) {
        s_bias = __ldg(bias + channel_idx);
        s_scale = __ldg(scale + channel_idx);
    }
    __syncthreads();

    if (idx + VEC-1 >= num_elements) return;

    const float4 in = *reinterpret_cast<const float4*>(input + idx);
    float4 out;

    out.x = (in.x + s_bias) * s_scale;
    out.y = (in.y + s_bias) * s_scale;
    out.z = (in.z + s_bias) * s_scale;
    out.w = (in.w + s_bias) * s_scale;

    out.x = 1.0f / (1.0f + __expf(-out.x));
    out.y = 1.0f / (1.0f + __expf(-out.y));
    out.z = 1.0f / (1.0f + __expf(-out.z));
    out.w = 1.0f / (1.0f + __expf(-out.w));

    *reinterpret_cast<float4*>(output + idx) = out;
}

torch::Tensor fused_bias_scale_sigmoid_cuda(torch::Tensor input, torch::Tensor bias, torch::Tensor scale) {
    auto output = torch::empty_like(input);
    const int num_elements = input.numel();
    const int channels = bias.size(0);
    const int elements_per_channel = input.size(2) * input.size(3);

    const int blocks_per_channel = ((num_elements / channels) + BLOCK_SIZE*VEC -1) / (BLOCK_SIZE*VEC);
    const int grid_size = channels * blocks_per_channel;

    fused_bias_scale_sigmoid_kernel<<<grid_size, BLOCK_SIZE>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        scale.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements,
        elements_per_channel,
        channels
    );

    return output;
}
"""

