#include <cuda_runtime.h>

#define BM 128
#define BN 128
#define BK 16
#define TM 8
#define TN 8

__global__ void matmul_transposed_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int K, int N) {
    extern __shared__ float smem[];
    float* As = smem;
    float* Bs = smem + BM * BK;

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int bx = blockIdx.x;
    const int by = blockIdx.y;

    const int row = bx * BM + ty * TM;
    const int col = by * BN + tx * TN;

    float accum[TM][TN] = {0.0f};

    const int A_stride = M;
    const int B_stride = N;

    for (int k0 = 0; k0 < K; k0 += BK) {
        // Load A tile (BMxBK)
        #pragma unroll
        for (int i = 0; i < BM; i += 64) {
            int m_inner = i + tx * 4;
            int k_inner = k0 + ty;
            if (m_inner < BM && k_inner < K) {
                float4 tmp = *reinterpret_cast<const float4*>(&A[k_inner * A_stride + bx * BM + m_inner]);
                As[(m_inner + 0) * BK + ty] = tmp.x;
                As[(m_inner + 1) * BK + ty] = tmp.y;
                As[(m_inner + 2) * BK + ty] = tmp.z;
                As[(m_inner + 3) * BK + ty] = tmp.w;
            }
        }

        // Load B tile (BKxBN)
        #pragma unroll
        for (int j = 0; j < BN; j += 64) {
            int n_inner = j + tx * 4;
            int k_inner = k0 + ty;
            if (n_inner < BN && k_inner < K) {
                float4 tmp = *reinterpret_cast<const float4*>(&B[k_inner * B_stride + by * BN + n_inner]);
