            }
        }

        __syncthreads();

        // Compute block matrix multiplication
        #pragma unroll
        for (int kk = 0; kk < BK; ++kk) {
            float a[TM];
            float b[TN];

            #pragma unroll
            for (int ti = 0; ti < TM; ++ti) {
