#include <torch/extension.h>
#include <cuda_fp16.h>

__device__ __forceinline__ float4 fast_swish4(float4 val) {
    return {
        val.x * __frcp_rn(1.0f + __expf(-val.x)),
        val.y * __frcp_rn(1.0f + __expf(-val.y)),
        val.z * __frcp_rn(1.0f + __expf(-val.z)),
        val.w * __frcp_rn(1.0f + __expf(-val.w))
    };
