__global__ void swish_kernel(const float* __restrict__ x,
                             float* __restrict__ out,
                             int num_elements) {
    constexpr int VEC_SIZE = 4;
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = gridDim.x * blockDim.x;
    const int num_vecs = num_elements / VEC_SIZE;

    for(int i = tid; i < num_vecs; i += stride) {
        float4 x_vec = *reinterpret_cast<const float4*>(x + i * VEC_SIZE);
        float4 out_vec = fast_swish4(x_vec);
        *reinterpret_cast<float4*>(out + i * VEC_SIZE) = out_vec;
    }

    const int remaining_start = num_vecs * VEC_SIZE;
    const int elem_idx = remaining_start + tid;
    if(elem_idx < num_elements) {
        const float val = x[elem_idx];
        out[elem_idx] = val * __frcp_rn(1.0f + __expf(-val));
    }
}

