        for (int i = ty * BLOCK + tx; i < chunk_size * kernel_size * kernel_size; i += BLOCK*BLOCK) {
            const int ic = ic_start + i / (kernel_size * kernel_size);
            const int k = i % (kernel_size * kernel_size);
            if (ic < ic_end) {
