                for (int ix = tx; ix < input_tile_w; ix += BLOCK) {
                    const int iw = tile_x * stride - padding + ix * dilation;
                    float val = 0.0f;
                    if (ih >= 0 && ih < input_h && iw >= 0 && iw < input_w) {
