        #pragma unroll
        for (int ic = 0; ic < chunk_size; ++ic) {
            #pragma unroll
            for (int kh = 0; kh < kernel_size; ++kh) {
                #pragma unroll
                for (int kw = 0; kw < kernel_size; ++kw) {
                    const int w_idx = ic * kernel_size * kernel_size + kh * kernel_size + kw;
                    const float w = w_smem[w_idx];

                    #pragma unroll
                    for (int dy = 0; dy < STRIDE; ++dy) {
                        const int oh = oh_start + dy;
                        if (oh >= output_h) continue;
                        #pragma unroll
                        for (int dx = 0; dx < STRIDE; ++dx) {
                            const int ow = ow_start + dx;
                            if (ow >= output_w) continue;

