                            const int iw = ow * stride - padding + kw * dilation;
                            const int iy = ih - (tile_y * stride - padding);
                            const int ix = iw - (tile_x * stride - padding);

                            if (iy >= 0 && iy < input_tile_h && ix >= 0 && ix < input_tile_w) {
