matmul_swish_scale_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_swish_scale_kernel(const float* x, const float* weight, const float* bias, float* out, float scaling_factor, int batch_size, int in_features, int out_features) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * out_features) {
        int batch_idx = idx / out_features;
        int out_idx = idx % out_features;
        float sum = 0.0f;
        for (int i = 0; i < in_features; i++) {
            sum += x[batch_idx * in_features + i] * weight[i * out_features + out_idx];
        }
        sum += bias[out_idx];
        float sigmoid = 1.0f / (1.0f + __expf(-sum));
        out[idx] = sum * sigmoid * scaling_factor;
    }
}

