fused_conv_activation_bn_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_conv_activation_bn_kernel(
    const float* input, const float* weight, const float* bias, 
    const float* running_mean, const float* running_var, 
    float* output, int batch_size, int in_channels, int out_channels, 
    int input_height, int input_width, int kernel_size, float eps, float momentum) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    int output_height = input_height - kernel_size + 1;
    int output_width = input_width - kernel_size + 1;
    int output_size = batch_size * out_channels * output_height * output_width;
    int kernel_radius = kernel_size / 2;

    for (int i = idx; i < output_size; i += stride) {
        int b = i / (out_channels * output_height * output_width);
        int oc = (i / (output_height * output_width)) % out_channels;
        int h = (i / output_width) % output_height;
        int w = i % output_width;

        float sum = 0.0f;

        for (int ic = 0; ic < in_channels; ++ic) {
            for (int kh = 0; kh < kernel_size; ++kh) {
                for (int kw = 0; kw < kernel_size; ++kw) {
                    int ih = h + kh - kernel_radius;
                    int iw = w + kw - kernel_radius;

                    if (ih >= 0 && ih < input_height && iw >= 0 && iw < input_width) {
                        int input_idx = b * (in_channels * input_height * input_width) + ic * (input_height * input_width) + ih * input_width + iw;
                        int weight_idx = oc * (in_channels * kernel_size * kernel_size) + ic * (kernel_size * kernel_size) + kh * kernel_size + kw;
                        sum += input[input_idx] * weight[weight_idx];
                    }
                }
            }
        }

        sum += bias[oc];

        // Apply activation: tanh(softplus(x)) * x
        float softplus = logf(1.0f + expf(sum));
        float tanh_softplus = tanhf(softplus);
        float activated = tanh_softplus * sum;

        // Apply batch normalization
        float mean = running_mean[oc];
        float var = running_var[oc];
        float normalized = (activated - mean) / sqrtf(var + eps);

        output[i] = normalized;
    }
}

