matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* a, const float* b, float* out, int batch_size, int in_features, int out_features) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * out_features) {
        int batch_idx = idx / out_features;
        int out_idx = idx % out_features;
        float sum = 0.0f;
        for (int i = 0; i < in_features; i++) {
            sum += a[batch_idx * in_features + i] * b[i * out_features + out_idx];
        }
        out[idx] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor a, torch::Tensor b) {
    auto batch_size = a.size(0);
    auto in_features = a.size(1);
    auto out_features = b.size(0);
    auto out = torch::zeros({batch_size, out_features}, torch::TensorOptions().device(a.device()).dtype(a.dtype()));

    const int block_size = 256;
    const int num_blocks = (batch_size * out_features + block_size - 1) / block_size;

    matmul_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), batch_size, in_features, out_features);

    return out;
}
"""

# Define the custom CUDA kernel for dropout
dropout_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <curand_kernel.h>

__global__ void generate_mask(float* mask, int size, float p) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        curandState_t state;
        curand_init(idx, 0, 0, &state);
        mask[idx] = curand_uniform(&state);
    }
}

__global__ void dropout_kernel(const float* x, float* out, float* mask, int size, float p) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        if (mask[idx] > p) {
            out[idx] = x[idx];
        } else {
            out[idx] = 0.0f;
        }
    }
}

torch::Tensor dropout_cuda(torch::Tensor x, float p) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);
    auto mask = torch::empty(size, torch::TensorOptions().device(x.device()).dtype(torch.float32));

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    generate_mask<<<num_blocks, block_size>>>(mask.data_ptr<float>(), size, p);
    dropout_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), mask.data_ptr<float>(), size, p);

    return out;
}
"""

