#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_ops_kernel(const float* x, const float* bias, float* out, int size, int channels, int depth, int height, int width) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        int c = (idx / (depth * height * width)) % channels;
        float val = x[idx];

        // LogSumExp
        float max_val = val;
        for (int i = 0; i < channels; ++i) {
            int offset = (idx / (depth * height * width)) * channels * depth * height * width + i * depth * height * width + (idx % (depth * height * width));
            float tmp = x[offset];
            if (tmp > max_val) max_val = tmp;
        }
        float sum_exp = 0.0f;
        for (int i = 0; i < channels; ++i) {
            int offset = (idx / (depth * height * width)) * channels * depth * height * width + i * depth * height * width + (idx % (depth * height * width));
            float tmp = x[offset];
            sum_exp += expf(tmp - max_val);
        }
        val = logf(sum_exp) + max_val;

        // HardSwish
        val = val * (1.0f / (1.0f + expf(-(val + 3.0f)))) / 6.0f;

        // Subtract bias
