import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Group Normalization
group_norm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void group_norm_kernel(const float* x, float* mean, float* var, int batch_size, int num_features, int num_groups, int dim1, int dim2) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int group_idx = blockIdx.y * blockDim.y + threadIdx.y;

    if (idx < dim1 * dim2 && group_idx < num_groups) {
        int group_size = num_features / num_groups;
        int group_start = group_idx * group_size;
        int group_end = (group_idx + 1) * group_size;

        float sum = 0.0f;
        float sum_sqr = 0.0f;

        for (int i = group_start; i < group_end; i++) {
            float val = x[idx * num_features + i];
            sum += val;
            sum_sqr += val * val;
        }

        mean[group_idx] = sum / group_size;
        var[group_idx] = sum_sqr / group_size - mean[group_idx] * mean[group_idx];
    }
}

__global__ void group_norm_kernel2(const float* x, float* out, const float* mean, const float* var, const float* weight, const float* bias, int batch_size, int num_features, int num_groups, int dim1, int dim2) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int feature_idx = blockIdx.y * blockDim.y + threadIdx.y;

    if (idx < dim1 * dim2 && feature_idx < num_features) {
        int group_idx = feature_idx / (num_features / num_groups);
        float norm_val = (x[idx * num_features + feature_idx] - mean[group_idx]) / sqrt(var[group_idx] + 1e-5f);
        out[idx * num_features + feature_idx] = weight[feature_idx] * norm_val + bias[feature_idx];
    }
}

torch::Tensor group_norm_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    auto batch_size = x.size(0);
    auto num_features = x.size(1);
    auto dim1 = x.size(2);
    auto dim2 = x.size(3);
    auto num_groups = num_features / (num_features / (int)weight.size(0));

    auto mean = torch::zeros({num_groups}, torch::kFloat32).to(x.device);
    auto var = torch::zeros({num_groups}, torch::kFloat32).to(x.device);
    auto out = torch::zeros_like(x);

    const int block_size_x = 256;
    const int block_size_y = 16;
    const int num_blocks_x = (dim1 * dim2 + block_size_x - 1) / block_size_x;
    const int num_blocks_y = (num_groups + block_size_y - 1) / block_size_y;

    dim3 block(block_size_x, block_size_y);
    dim3 grid(num_blocks_x, num_blocks_y);

    group_norm_kernel<<<grid, block>>>(x.data_ptr<float>(), mean.data_ptr<float>(), var.data_ptr<float>(), batch_size, num_features, num_groups, dim1, dim2);

    group_norm_kernel2<<<dim3(num_blocks_x, num_features, 1), dim3(block_size_x, block_size_y, 1)>>>(x.data_ptr<float>(), out.data_ptr<float>(), mean.data_ptr<float>(), var.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), batch_size, num_features, num_groups, dim1, dim2);

    return out;
}
"""

group_norm_cpp_source = (
    "torch::Tensor group_norm_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias);"
)

# Compile the inline CUDA code for Group Normalization
group_norm = load_inline(
    name="group_norm",
    cpp_sources=group_norm_cpp_source,
    cuda_sources=group_norm_source,
    functions=["group_norm_cuda"],
    verbose=True,
    extra_cflags=["-arch=sm_89"],
    extra_ldflags=["-arch=sm_89"],
)


class ModelNew(nn.Module):
    def __init__(self, num_features: int, num_groups: int):
        super(ModelNew, self).__init__()
        self.group_norm = group_norm
        self.weight = torch.ones(num_features)
        self.bias = torch.zeros(num_features)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.group_norm.group_norm_cuda(x, self.weight, self.bias)
