__global__ void compute_mean_kernel(const float* x, float* mean, int batch_size, int features, int dim1, int dim2) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * features) {
        float sum = 0.0f;
        for (int i = 0; i < dim1 * dim2; i++) {
            sum += x[idx * dim1 * dim2 + i];
        }
        mean[idx] = sum / (dim1 * dim2);
    }
}

__global__ void compute_inv_var_kernel(const float* x, const float* mean, float* inv_var, int batch_size, int features, int dim1, int dim2) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * features) {
        float sum = 0.0f;
        for (int i = 0; i < dim1 * dim2; i++) {
            float diff = x[idx * dim1 * dim2 + i] - mean[idx];
            sum += diff * diff;
        }
        inv_var[idx] = 1.0f / sqrt(sum / (dim1 * dim2) + 1e-5f);
    }
}

__global__ void layer_norm_kernel(const float* x, float* out, const float* mean, const float* inv_var, int batch_size, int features, int dim1, int dim2) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * features * dim1 * dim2) {
