    int input_depth, int input_height, int input_width, int output_depth, int output_height, int output_width, 
    int kernel_size, int stride, int padding, float eps, float momentum, int batch_size) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * out_channels * output_depth * output_height * output_width) {
        int n = idx / (out_channels * output_depth * output_height * output_width);
        int c = (idx / (output_depth * output_height * output_width)) % out_channels;
        int d = (idx / (output_height * output_width)) % output_depth;
        int h = (idx / output_width) % output_height;
        int w = idx % output_width;

        float sum = 0.0f;
        for (int ic = 0; ic < in_channels; ++ic) {
            for (int kd = 0; kd < kernel_size; ++kd) {
                for (int kh = 0; kh < kernel_size; ++kh) {
