        int c = (idx / ((depth - kernel_size + 1) * (height - kernel_size + 1) * (width - kernel_size + 1))) % out_channels;
        int d = (idx / ((height - kernel_size + 1) * (width - kernel_size + 1))) % (depth - kernel_size + 1);
        int h = (idx / (width - kernel_size + 1)) % (height - kernel_size + 1);
        int w = idx % (width - kernel_size + 1);

        float sum = 0.0f;
        for (int ic = 0; ic < in_channels; ++ic) {
            for (int kd = 0; kd < kernel_size; ++kd) {
                for (int kh = 0; kh < kernel_size; ++kh) {
                    for (int kw = 0; kw < kernel_size; ++kw) {
                        int input_d = d + kd;
                        int input_h = h + kh;
                        int input_w = w + kw;

                        int input_idx = b * (in_channels * depth * height * width) + 
                                       ic * (depth * height * width) + 
                                       input_d * (height * width) + 
                                       input_h * width + 
