                        int weight_idx = c * (in_channels * kernel_size * kernel_size * kernel_size) + 
                                        ic * (kernel_size * kernel_size * kernel_size) + 
                                        kd * (kernel_size * kernel_size) + 
                                        kh * kernel_size + 
                                        kw;
                        sum += input[input_idx] * conv_weight[weight_idx];
