conv_transpose2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose2d_kernel(const float* input, const float* weight, float* output, 
                                      int batch_size, int in_channels, int out_channels, 
                                      int input_height, int input_width, int kernel_height, int kernel_width, 
                                      int stride_height, int stride_width, int padding_height, int padding_width) {
    int batch_idx = blockIdx.x;
    int out_channel_idx = blockIdx.y;
    int out_height_idx = blockIdx.z;
    int out_width_idx = threadIdx.x;

    if (batch_idx < batch_size && out_channel_idx < out_channels && out_height_idx < (input_height - 1) * stride_height + kernel_height && out_width_idx < (input_width - 1) * stride_width + kernel_width) {
        float sum = 0.0f;
        for (int in_channel_idx = 0; in_channel_idx < in_channels; in_channel_idx++) {
            for (int kernel_height_idx = 0; kernel_height_idx < kernel_height; kernel_height_idx++) {
                for (int kernel_width_idx = 0; kernel_width_idx < kernel_width; kernel_width_idx++) {
                    int input_height_idx = out_height_idx - kernel_height_idx + padding_height;
                    int input_width_idx = out_width_idx - kernel_width_idx + padding_width;
                    if (input_height_idx >= 0 && input_height_idx < input_height && input_width_idx >= 0 && input_width_idx < input_width) {
                        sum += input[batch_idx * in_channels * input_height * input_width + in_channel_idx * input_height * input_width + input_height_idx * input_width + input_width_idx] * 
                               weight[out_channel_idx * in_channels * kernel_height * kernel_width + in_channel_idx * kernel_height * kernel_width + kernel_height_idx * kernel_width + kernel_width_idx];
                    }
                }
            }
        }
        output[batch_idx * out_channels * ((input_height - 1) * stride_height + kernel_height) * ((input_width - 1) * stride_width + kernel_width) + out_channel_idx * ((input_height - 1) * stride_height + kernel_height) * ((input_width - 1) * stride_width + kernel_width) + out_height_idx * ((input_width - 1) * stride_width + kernel_width) + out_width_idx] = sum;
    }
}

torch::Tensor conv_transpose2d_cuda(torch::Tensor input, torch::Tensor weight, 
                                   int batch_size, int in_channels, int out_channels, 
                                   int input_height, int input_width, int kernel_height, int kernel_width, 
                                   int stride_height, int stride_width, int padding_height, int padding_width) {
    auto output = torch::zeros({batch_size, out_channels, (input_height - 1) * stride_height + kernel_height, (input_width - 1) * stride_width + kernel_width}, torch::TensorOptions().dtype(torch::kFloat32).device(torch::kCUDA, 0));

    const int block_size_x = 256;
    const int num_blocks_x = ((input_width - 1) * stride_width + kernel_width + block_size_x - 1) / block_size_x;
    const int num_blocks_y = out_channels;
    const int num_blocks_z = (input_height - 1) * stride_height + kernel_height;

    dim3 block(block_size_x, 1, 1);
    dim3 grid(num_blocks_x, num_blocks_y, num_blocks_z);

    conv_transpose2d_kernel<<<grid, block>>>(input.data_ptr<float>(), weight.data_ptr<float>(), output.data_ptr<float>(), 
                                                                                                        batch_size, in_channels, out_channels, 
                                                                                                        input_height, input_width, kernel_height, kernel_width, 
                                                                                                        stride_height, stride_width, padding_height, padding_width);

    return output;
}
