__global__ void conv_transpose2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int KERNEL_H, int KERNEL_W,
    int STRIDE_H, int STRIDE_W,
    int PADDING_H, int PADDING_W,
    int N, int C_in, int H_in, int W_in,
    int C_out_per_group,
    int output_padding_h, int output_padding_w,
    int groups,
    int H_out, int W_out
) {
    extern __shared__ float smem[];
    const int C_in_per_group = C_in / groups;
    const int weight_smem_size = C_in_per_group * KERNEL_H * KERNEL_W;
    float* weight_smem = smem;

    const int n = blockIdx.z;
    const int g = blockIdx.y;
    const int c_out_in_group = blockIdx.x;
    const int c_out = g * C_out_per_group + c_out_in_group;

    // Load weights into shared memory
    for (int i = threadIdx.x; i < weight_smem_size; i += blockDim.x) {
        int c = i / (KERNEL_H * KERNEL_W);
        int k = i % (KERNEL_H * KERNEL_W);
        int ky = k / KERNEL_W;
        int kw = k % KERNEL_W;
        weight_smem[i] = weight[((g * C_in_per_group + c) * C_out_per_group + c_out_in_group) * KERNEL_H * KERNEL_W + ky * KERNEL_W + kw];
    }
    __syncthreads();

    // Process spatial dimensions
    for (int hw = threadIdx.x; hw < H_out * W_out; hw += blockDim.x) {
        const int h_out = hw / W_out;
        const int w_out = hw % W_out;
        float sum = 0.0f;

        for (int ky = 0; ky < KERNEL_H; ++ky) {
            for (int kw = 0; kw < KERNEL_W; ++kw) {
                const int h_in = (h_out - ky + PADDING_H) / STRIDE_H;
                const int w_in = (w_out - kw + PADDING_W) / STRIDE_W;

                if ((h_out - ky + PADDING_H) % STRIDE_H != 0) continue;
