convolution_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void convolution_kernel(const float* input, const float* weight, float* output, 
                                   int batch_size, int in_channels, int out_channels, 
                                   int height, int width, int kernel_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * out_channels * height * width) {
        int b = idx / (out_channels * height * width);
        int c = (idx / (height * width)) % out_channels;
        int h = (idx / width) % height;
        int w = idx % width;

        float sum = 0.0f;
        for (int i = 0; i < in_channels; i++) {
            for (int j = 0; j < kernel_size; j++) {
                for (int k = 0; k < kernel_size; k++) {
                    int input_idx = b * in_channels * height * width + i * height * width + 
                                    (h + j) * width + (w + k);
                    int weight_idx = c * in_channels * kernel_size * kernel_size + 
                                     i * kernel_size * kernel_size + j * kernel_size + k;
                    sum += input[input_idx] * weight[weight_idx];
                }
            }
        }
        output[idx] = sum;
    }
}

torch::Tensor convolution_cuda(torch::Tensor input, torch::Tensor weight) {
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto out_channels = weight.size(0);
    auto height = input.size(2);
    auto width = input.size(3);
    auto kernel_size = weight.size(2);

    auto output = torch::zeros({batch_size, out_channels, height, width}, input.options());

    const int block_size = 256;
    const int num_blocks = (batch_size * out_channels * height * width + block_size - 1) / block_size;

    convolution_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), weight.data_ptr<float>(), 
                                                  output.data_ptr<float>(), batch_size, in_channels, 
                                                  out_channels, height, width, kernel_size);

    return output;
}
"""

# Define the custom CUDA kernel for instance normalization
instance_norm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void instance_norm_kernel(const float* input, float* output, float* mean, float* inv_std, 
                                    int batch_size, int channels, int height, int width) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * channels * height * width) {
        int b = idx / (channels * height * width);
        int c = (idx / (height * width)) % channels;
        int h = (idx / width) % height;
        int w = idx % width;

        output[idx] = (input[idx] - mean[b * channels + c]) * inv_std[b * channels + c];
    }
}

torch::Tensor instance_norm_cuda(torch::Tensor input) {
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);

    auto mean = torch::zeros({batch_size, channels}, input.options());
    auto inv_std = torch::zeros({batch_size, channels}, input.options());

    // Calculate mean and inv_std
    for (int b = 0; b < batch_size; b++) {
        for (int c = 0; c < channels; c++) {
            float sum = 0.0f;
            for (int h = 0; h < height; h++) {
                for (int w = 0; w < width; w++) {
                    int idx = b * channels * height * width + c * height * width + h * width + w;
                    sum += input[idx].item<float>();
                }
            }
            mean[b * channels + c] = sum / (height * width);
            float sum_squared = 0.0f;
            for (int h = 0; h < height; h++) {
                for (int w = 0; w < width; w++) {
                    int idx = b * channels * height * width + c * height * width + h * width + w;
                    sum_squared += powf(input[idx].item<float>() - mean[b * channels + c].item<float>(), 2);
                }
            }
            float var = sum_squared / (height * width) + 1e-5f;
            inv_std[b * channels + c] = 1.0f / sqrtf(var);
        }
    }

    auto output = torch::zeros({batch_size, channels, height, width}, input.options());

    const int block_size = 256;
    const int num_blocks = (batch_size * channels * height * width + block_size - 1) / block_size;

    instance_norm_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), 
                                                    mean.data_ptr<float>(), inv_std.data_ptr<float>(), 
                                                    batch_size, channels, height, width);

    return output;
}
"""

