    int kernel_size_h, int kernel_size_w, int stride_h, int stride_w,
    int padding_h, int padding_w, int dilation_h, int dilation_w) {

    int out_height = (height + 2 * padding_h - (dilation_h * (kernel_size_h - 1) + 1)) / stride_h + 1;
    int out_width = (width + 2 * padding_w - (dilation_w * (kernel_size_w - 1) + 1)) / stride_w + 1;

    int n = blockIdx.x; // batch index
    int c = blockIdx.y; // channel index
    int h = threadIdx.x; // output height index
    int w = threadIdx.y; // output width index

    if (h < out_height && w < out_width) {
        float value = 0.0f;
        for (int kh = 0; kh < kernel_size_h; ++kh) {
            for (int kw = 0; kw < kernel_size_w; ++kw) {
                int ih = h * stride_h - padding_h + kh * dilation_h;
                int iw = w * stride_w - padding_w + kw * dilation_w;
