    bool has_bias
) {
    int l_out = blockIdx.x * blockDim.x + threadIdx.x;
    int out_c = blockIdx.y;
    int b = blockIdx.z;

    if (l_out >= output_length || out_c >= out_channels || b >= batch_size) return;

    float val = 0.0f;

    for (int in_c = 0; in_c < in_channels; ++in_c) {
        for (int k = 0; k < kernel_size; ++k) {
            int k_offset = k * dilation;
            int l_in = (l_out + padding - k_offset) / stride;
            int remainder = (l_out + padding - k_offset) % stride;

