    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * out_channels * depth * height * width) {
        int b = idx / (out_channels * depth * height * width);
        int c = (idx / (depth * height * width)) % out_channels;
        int d = (idx / (height * width)) % depth;
        int h = (idx / width) % height;
        int w = idx % width;

        float sum = 0.0f;
        for (int i = 0; i < in_channels; i++) {
            for (int kd = 0; kd < kernel_depth; kd++) {
                for (int kh = 0; kh < kernel_height; kh++) {
                    for (int kw = 0; kw < kernel_width; kw++) {
                        int id = d * stride_depth - padding_depth + kd - output_padding_depth;
                        int ih = h * stride_height - padding_height + kh - output_padding_height;
                        int iw = w * stride_width - padding_width + kw - output_padding_width;
                        if (id >= 0 && id < depth && ih >= 0 && ih < height && iw >= 0 && iw < width) {
