    const int n = blockIdx.z;
    const int c = blockIdx.y;
    const int h_out_start = blockIdx.x * TILE_H;

    __shared__ float smem_weights[KERNEL_SIZE];
    int tid = threadIdx.x + threadIdx.y * blockDim.x;
    for (int k = tid; k < KERNEL_SIZE; k += blockDim.x * blockDim.y) {
