# Define the custom CUDA kernel for fused BatchNorm2d + ReLU + Conv2d + AvgPool2d
fused_transition_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_transition_kernel(
    const float* input, const float* weight, const float* running_mean, const float* running_var,
    float* output, int batch_size, int num_input_features, int num_output_features, int height, int width,
    float eps, float momentum, float alpha, int kernel_size, int stride) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int h = (idx / width) % height;
    int w = idx % width;
    int c = (idx / (height * width)) % num_input_features;
    int n = idx / (height * width * num_input_features);

    if (n < batch_size && c < num_input_features && h < height && w < width) {
        float mean = running_mean[c];
        float var = running_var[c];
        float inv_std = 1.0f / sqrt(var + eps);
        float normalized = (input[idx] - mean) * inv_std;

        // ReLU
        float relu = fmaxf(normalized, 0.0f);

        // Conv2d
        float conv = 0.0f;
        for (int oc = 0; oc < num_output_features; ++oc) {
            conv += relu * weight[oc * num_input_features + c];
        }

        // AvgPool2d
        if (h % stride == 0 && w % stride == 0) {
            int pooled_h = h / stride;
            int pooled_w = w / stride;
            int pooled_idx = n * (num_output_features * (height / stride) * (width / stride)) +
                             oc * ((height / stride) * (width / stride)) +
                             pooled_h * (width / stride) + pooled_w;
            atomicAdd(&output[pooled_idx], conv / (kernel_size * kernel_size));
        }
    }
}

